#include <bits/stdc++.h>
using namespace std;

#define LL long long
#define ULL unsigned LL
#define fi first
#define se second
#define pb push_back
const int inf = 0x3f3f3f3f;

int px[10000], py[10000];
int head[10000], to[100000], ct[100000], w[100000], nt[100000];
int d[10000], vis[10000];
int pre[10000], id[10000];
int s, t, tot;

void add_edge(int u, int v, int flow, int cost) {
    to[tot] = v; ct[tot] = cost; w[tot] = flow; nt[tot] = head[u]; head[u] = tot++;
    to[tot] = u; ct[tot] = -cost; w[tot] = 0; nt[tot] = head[v]; head[v] = tot++;
}

void initialize() {
    memset(head, -1, sizeof(head));
    tot = 0;
}

bool spfa(int s, int t) {
    std::queue<int> q;
    memset(d, 0x3f, sizeof(d));
    memset(vis, 0, sizeof(vis));
    memset(pre, -1, sizeof(pre));
    d[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        vis[u] = 0;
        for (int i = head[u]; i != -1; i = nt[i]) {
            if (w[i] > 0 && d[to[i]] > d[u] + ct[i]) {
                d[to[i]] = d[u] + ct[i];
                pre[to[i]] = u;
                id[to[i]] = i;
                if (!vis[to[i]]) {
                    vis[to[i]] = 1;
                    q.push(to[i]);
                }
            }
        }
    }
    return d[t] < 0x3f3f3f3f;
}

int minCostFlow(int s, int t) {
    int totalCost = 0, flow = 0;
    while (spfa(s, t)) {
        int f = inf;
        for (int i = t; i != s; i = pre[i]) {
            f = min(f, w[id[i]]);
        }
        for (int i = t; i != s; i = pre[i]) {
            w[id[i]] -= f;
            w[id[i] ^ 1] += f;
        }
        flow += f;
        totalCost += d[t] * f;
    }
    return totalCost;
}

int main() {
    initialize();
    int n, m, k, c, d;
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    s = 0; t = n * 100 + 1;
    for (int i = 1; i <= 100; ++i)
        add_edge(i, t, 100, 0);
    for (int i = 1, v; i <= k; ++i) {
        scanf("%d", &v);
        add_edge(s, (v - 1) * 100 + 1, 1, 0);
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j < 100; ++j) {
            add_edge((i - 1) * 100 + j, (i - 1) * 100 + j + 1, 100, c);
        }
    }
    for (int i = 1, u, v; i <= m; ++i) {
        scanf("%d%d", &u, &v);
        for (int j = 1; j < 100; ++j) {
            int idx = (u - 1) * 100 + j;
            int idy = (v - 1) * 100 + j + 1;
            for (int k = 1; k <= 20; ++k) {
                add_edge(idx, idy, 1, c + (k * k - (k - 1) * (k - 1)) * d);
            }
        }
        for (int j = 1; j < 100; ++j) {
            int idx = (v - 1) * 100 + j;
            int idy = (u - 1) * 100 + j + 1;
            for (int k = 1; k <= 20; ++k) {
                add_edge(idx, idy, 1, c + (k * k - (k - 1) * (k - 1)) * d);
            }
        }
    }
    printf("%d\n", minCostFlow(s, t));
    return 0;
}
